// Soundbar fullness index — record JAH-GPCS-SOUNDBAR-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"channels": 2, "watts": 20, "price_usd": 60};
var value = (m.channels*m.watts/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-SOUNDBAR-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-SOUNDBAR-000001|' + value.toFixed(2) + ' fullness index');

